import { Component, EventEmitter, Input, OnInit, Output, computed, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormArray, FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { forkJoin } from 'rxjs';
import { CatalogService, InventoryService } from '../../core/services/domain.services';
import { ToastService } from '../../core/services/toast.service';
import { Category, Ingredient } from '../../core/models/models';
import { IconComponent } from '../../shared/icon/icon.component';
import { SpinnerComponent } from '../../shared/ui/misc';

@Component({
  selector: 'app-food-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, IconComponent, SpinnerComponent],
  templateUrl: './food-form.component.html',
  styleUrl: './food-form.component.scss',
})
export class FoodFormComponent implements OnInit {
  @Input() foodId: number | null = null;
  @Output() saved = new EventEmitter<void>();
  @Output() cancelled = new EventEmitter<void>();

  private fb = inject(FormBuilder);
  private catalog = inject(CatalogService);
  private inventory = inject(InventoryService);
  private toast = inject(ToastService);

  loading = signal(true);
  saving = signal(false);
  categories = signal<Category[]>([]);
  ingredients = signal<Ingredient[]>([]);

  form = this.fb.nonNullable.group({
    name: ['', Validators.required],
    sku: ['', Validators.required],
    categoryId: [null as number | null, Validators.required],
    description: [''],
    imageUrl: [''],
    sellingPrice: [0, [Validators.required, Validators.min(0.01)]],
    costPrice: [0, Validators.min(0)],
    packagingCost: [0, Validators.min(0)],
    otherCost: [0, Validators.min(0)],
    taxPercent: [5, [Validators.min(0), Validators.max(100)]],
    isVeg: [true],
    preparationTimeMinutes: [5, Validators.min(0)],
    isAvailable: [true],
    recipe: this.fb.array([] as any[]),
  });

  get recipe(): FormArray { return this.form.get('recipe') as FormArray; }

  ngOnInit() {
    forkJoin({ cats: this.catalog.categories(), ings: this.inventory.allIngredients() }).subscribe(({ cats, ings }) => {
      this.categories.set(cats); this.ingredients.set(ings);
      if (this.foodId) {
        this.catalog.foodItem(this.foodId).subscribe(f => {
          this.form.patchValue({
            name: f.name, sku: f.sku, categoryId: f.categoryId, description: f.description ?? '',
            imageUrl: f.imageUrl ?? '', sellingPrice: f.sellingPrice, costPrice: f.costPrice,
            packagingCost: f.packagingCost, otherCost: f.otherCost, taxPercent: f.taxPercent,
            isVeg: f.isVeg, preparationTimeMinutes: f.preparationTimeMinutes, isAvailable: f.isAvailable,
          });
          f.recipe.forEach(r => this.addRecipeRow(r.ingredientId, r.quantity));
          this.loading.set(false);
        });
      } else { this.loading.set(false); }
    });
  }

  addRecipeRow(ingredientId: number | null = null, quantity = 0) {
    this.recipe.push(this.fb.nonNullable.group({
      ingredientId: [ingredientId, Validators.required],
      quantity: [quantity, [Validators.required, Validators.min(0.001)]],
    }));
  }
  removeRecipeRow(i: number) { this.recipe.removeAt(i); }

  unitFor(ingredientId: number): string {
    return this.ingredients().find(i => i.id === +ingredientId)?.unit ?? '';
  }

  // live profit preview
  ingredientCost = computed(() => 0); // replaced by method below (signals can't read form easily)
  calcIngredientCost(): number {
    return this.recipe.controls.reduce((sum, c) => {
      const ing = this.ingredients().find(i => i.id === +c.get('ingredientId')!.value);
      return sum + (ing ? ing.costPerUnit * (+c.get('quantity')!.value || 0) : 0);
    }, 0);
  }
  totalCost(): number {
    const v = this.form.getRawValue();
    return this.calcIngredientCost() + (+v.packagingCost || 0) + (+v.otherCost || 0);
  }
  margin(): number {
    const price = +this.form.getRawValue().sellingPrice || 0;
    if (!price) return 0;
    return Math.round(((price - this.totalCost()) / price) * 100);
  }

  submit() {
    if (this.form.invalid) { this.form.markAllAsTouched(); this.toast.error('Please fix the form errors.'); return; }
    this.saving.set(true);
    const v = this.form.getRawValue();
    const body = { ...v, recipe: v.recipe.map((r: any) => ({ ingredientId: +r.ingredientId, quantity: +r.quantity })) };
    this.catalog.saveFoodItem(this.foodId, body).subscribe({
      next: () => { this.saving.set(false); this.toast.success('Food item saved.'); this.saved.emit(); },
      error: () => this.saving.set(false),
    });
  }
}
