import { Component, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Subject, debounceTime, distinctUntilChanged } from 'rxjs';
import { CatalogService } from '../../core/services/domain.services';
import { AuthService } from '../../core/services/auth.service';
import { ToastService } from '../../core/services/toast.service';
import { ConfirmService } from '../../shared/ui/confirm';
import { Category, FoodItem, PagedResult } from '../../core/models/models';
import { IconComponent } from '../../shared/icon/icon.component';
import { MoneyPipe } from '../../shared/pipes/money.pipe';
import { LoadingComponent, EmptyStateComponent } from '../../shared/ui/misc';
import { PaginatorComponent } from '../../shared/ui/paginator';
import { FoodFormComponent } from './food-form.component';

@Component({
  selector: 'app-food-items',
  standalone: true,
  imports: [CommonModule, FormsModule, IconComponent, MoneyPipe, LoadingComponent,
    EmptyStateComponent, PaginatorComponent, FoodFormComponent],
  templateUrl: './food-items.component.html',
})
export class FoodItemsComponent {
  private catalog = inject(CatalogService);
  private toast = inject(ToastService);
  private confirm = inject(ConfirmService);
  auth = inject(AuthService);

  loading = signal(true);
  result = signal<PagedResult<FoodItem> | null>(null);
  categories = signal<Category[]>([]);
  page = signal(1);
  search = signal('');
  categoryId = signal<string>('');
  isVeg = signal<string>('');
  isAvailable = signal<string>('');

  formOpen = signal(false);
  editId = signal<number | null>(null);
  private searchSubject = new Subject<string>();

  canManage = this.auth.hasRole('Admin', 'Manager');

  constructor() {
    this.catalog.categories().subscribe(c => this.categories.set(c));
    this.searchSubject.pipe(debounceTime(300), distinctUntilChanged()).subscribe(v => { this.search.set(v); this.page.set(1); this.load(); });
    this.load();
  }

  load() {
    this.loading.set(true);
    this.catalog.foodItems({
      page: this.page(), pageSize: 12, search: this.search(),
      categoryId: this.categoryId(), isVeg: this.isVeg(), isAvailable: this.isAvailable(),
    }).subscribe({ next: r => { this.result.set(r); this.loading.set(false); }, error: () => this.loading.set(false) });
  }

  onSearch(v: string) { this.searchSubject.next(v); }
  changeFilter() { this.page.set(1); this.load(); }
  goPage(p: number) { this.page.set(p); this.load(); }

  add() { this.editId.set(null); this.formOpen.set(true); }
  edit(f: FoodItem) { this.editId.set(f.id); this.formOpen.set(true); }
  onSaved() { this.formOpen.set(false); this.load(); }

  async remove(f: FoodItem) {
    const ok = await this.confirm.ask({ title: 'Delete food item?', message: `“${f.name}” will be removed.`, confirmText: 'Delete', danger: true });
    if (!ok) return;
    this.catalog.deleteFoodItem(f.id).subscribe({ next: () => { this.toast.success('Food item deleted.'); this.load(); } });
  }
}
